#!/usr/bin/env python3
"""DAY329 [DEBIAN-FECHA-D329] DEBT-LAB-KERNEL-HOMOGENEO-001, commit 1 de 2: la fecha de Debian del laboratorio.

Nuevos: ansible/inventory/group_vars/all.yml (argus_debian_snapshot, argus_lab_llamada_vm_limite_s),
scripts/emecas/lab_comun.rb (su validación) y scripts/emecas/test_lab_comun.rb.
Vagrantfile: carga all.yml (para si la fecha falta o está mal), aprovisionador debian-fecha tras apt-espera, y el
bookworm-backports de Suricata en snapshot.debian.org a esa fecha.

Uso (Mac, raíz del repo): python3 -I scripts/etcd_ha/d329_debian_fecha.py [--apply]
Sin --apply solo comprueba. Con --apply escribe, y solo si TODO cuadra: sha256 de partida de cada fichero que modifica,
cada ancla exactamente las veces esperadas y ningún fichero nuevo ya existente. Si algo falla no escribe nada.
"""
import hashlib, os, sys

NUEVOS = {'ansible/inventory/group_vars/all.yml': ('# aRGus NDR -- group_vars de TODOS los grupos del laboratorio (todas las lentes: argus, suricata, zeek, wazuh)\n# [DEBIAN-FECHA-D329] Fuente única de lo que es común a todas las VMs. Lo propio de cada lente va en su fichero\n# (argus_dev.yml; y suricata_dev.yml, zeek_dev.yml... cuando lleguen, DEBT-LAB-VERSIONES-TERCEROS-001). Los valida\n# scripts/emecas/lab_comun.rb, que leen el Vagrantfile y make kernel-homogeneo.\n\n# [DEBIAN-FECHA-D329] DEBT-LAB-KERNEL-HOMOGENEO-001 (decisión de Alonso DAY328-329): todas las VMs del laboratorio con\n# el mismo Debian. Todas las fuentes de Debian (bookworm, bookworm-updates, bookworm-security y el bookworm-backports\n# de Suricata) apuntan a snapshot.debian.org en esta marca, y el aprovisionador debian-fecha deja cada VM en ese estado\n# (full-upgrade). El kernel sale de la fecha: el que pide linux-image-amd64 en ella (make kernel-homogeneo lo comprueba\n# con uname -r en todas las VMs). Medido DAY329: en 20261115T000000Z, linux-image-amd64 6.1.190-1 ->\n# linux-image-6.1.0-54-amd64, el kernel con el que pasó el EMECAS de DAY327; el 6.1.0-55 (6.1.192-1) sufre el oops de\n# ext4 de DAY328 (Debian #1154153).\n# Formato: AAAAMMDDTHHMMSSZ (UTC), una fecha real. Límites: desde 20240905T000000Z (la caja debian/bookworm64\n# 12.20240905.1: una fecha anterior bajaría paquetes) hasta el momento actual. Sin defecto en ningún sitio: si falta o\n# está mal, Vagrant para. Es un error de fabricante (de aRGus, no del despliegue): el laboratorio lo ve antes que nadie.\n# Para cambiarla: la fecha más reciente que pase un EMECAS+++ desde cero.\nargus_debian_snapshot: "20261115T000000Z"\n\n# [DEBIAN-FECHA-D329] tiempo límite, en segundos, de cada llamada del anfitrión a una VM en las comprobaciones del lab\n# (make kernel-homogeneo). Una VM que no contesta da ❌ en vez de colgar la corrida (lección DAY328). Entero [10, 600].\n# Ausente o mal: 60, avisando.\nargus_lab_llamada_vm_limite_s: 60\n', 420), 'scripts/emecas/lab_comun.rb': ('# frozen_string_literal: true\n# [DEBIAN-FECHA-D329] aRGus NDR -- valores comunes a todas las lentes del laboratorio\n# (ansible/inventory/group_vars/all.yml). Una sola validación para el Vagrantfile y para make kernel-homogeneo.\n#\n#   argus_debian_snapshot          AAAAMMDDTHHMMSSZ (UTC), fecha real, de 20240905T000000Z al momento actual.\n#                                  Sin defecto: falta o mal -> error (de fabricante); quien lo use para.\n#   argus_lab_llamada_vm_limite_s  entero [10, 600]. Falta o mal -> 60, con aviso.\n#\n# Ningún valor se lee en silencio: cargar devuelve, además de errores y avisos, una línea por campo con el valor\n# aplicado y de dónde sale.\n#\n# Uso (anfitrión): ruby lab_comun.rb fecha <all.yml>   -> imprime la fecha; errores y avisos a stderr; rc 1 si error\n#                  ruby lab_comun.rb limite <all.yml>  -> imprime el límite; la línea de origen a stderr\nrequire "yaml"\n\nmodule ArgusLabComun\n  FECHA_RE = /\\A\\d{8}T\\d{6}Z\\z/\n  FECHA_MIN = "20240905T000000Z"\n  LIMITE_DEFECTO = 60\n  LIMITE_MIN = 10\n  LIMITE_MAX = 600\n  FABRICANTE = "ERROR DE FABRICANTE: avisar a aRGus (el laboratorio debió verlo antes); no es un fallo del despliegue"\n\n  # -> [fecha_o_nil, limite, errores, avisos, aplicados]\n  def self.cargar(ruta, ahora = Time.now.utc)\n    errores = []\n    avisos = []\n    aplicados = []\n    datos = begin\n      YAML.safe_load(File.read(ruta)) || {}\n    rescue StandardError => e\n      return [nil, LIMITE_DEFECTO, ["#{ruta}: no se puede leer (#{e.class}: #{e.message}). #{FABRICANTE}"], [], []]\n    end\n    datos = {} unless datos.is_a?(Hash)\n\n    fecha = nil\n    f = datos["argus_debian_snapshot"]\n    formato = "formato AAAAMMDDTHHMMSSZ (UTC), de #{FECHA_MIN} al momento actual"\n    if f.nil?\n      errores << "argus_debian_snapshot: falta en #{ruta} (#{formato}). #{FABRICANTE}"\n    elsif !(f.is_a?(String) && FECHA_RE.match?(f))\n      errores << "argus_debian_snapshot: #{f.inspect} mal formado en #{ruta} (#{formato}). #{FABRICANTE}"\n    else\n      t = begin\n        Time.utc(f[0, 4].to_i, f[4, 2].to_i, f[6, 2].to_i, f[9, 2].to_i, f[11, 2].to_i, f[13, 2].to_i)\n      rescue ArgumentError\n        nil\n      end\n      if t.nil? || t.strftime("%Y%m%dT%H%M%SZ") != f\n        errores << "argus_debian_snapshot: #{f} no es una fecha real en #{ruta} (#{formato}). #{FABRICANTE}"\n      elsif f < FECHA_MIN || t > ahora\n        errores << "argus_debian_snapshot: #{f} fuera de límites en #{ruta} (#{formato}). #{FABRICANTE}"\n      else\n        fecha = f\n        aplicados << "argus_debian_snapshot=#{f} (de #{ruta})"\n      end\n    end\n\n    limite = LIMITE_DEFECTO\n    l = datos["argus_lab_llamada_vm_limite_s"]\n    rango = "entero [#{LIMITE_MIN}, #{LIMITE_MAX}]"\n    if l.nil?\n      avisos << "argus_lab_llamada_vm_limite_s: falta en #{ruta} (#{rango}); se aplica #{LIMITE_DEFECTO}"\n      aplicados << "argus_lab_llamada_vm_limite_s=#{LIMITE_DEFECTO} (defecto del código: falta en #{ruta})"\n    elsif !l.is_a?(Integer) || l < LIMITE_MIN || l > LIMITE_MAX\n      avisos << "argus_lab_llamada_vm_limite_s: #{l.inspect} mal en #{ruta} (#{rango}); se aplica #{LIMITE_DEFECTO}"\n      aplicados << "argus_lab_llamada_vm_limite_s=#{LIMITE_DEFECTO} (defecto del código: #{l.inspect} mal formado)"\n    else\n      limite = l\n      aplicados << "argus_lab_llamada_vm_limite_s=#{l} (de #{ruta})"\n    end\n\n    [fecha, limite, errores, avisos, aplicados]\n  end\nend\n\nif $PROGRAM_NAME == __FILE__\n  campo, ruta = ARGV\n  unless %w[fecha limite].include?(campo) && ruta\n    warn "uso: ruby #{File.basename(__FILE__)} fecha|limite <all.yml>"\n    exit 2\n  end\n  fecha, limite, errores, avisos, aplicados = ArgusLabComun.cargar(ruta)\n  avisos.each { |a| warn "[DEBIAN-FECHA-D329] ⚠️  AVISO #{a}" }\n  if campo == "fecha"\n    unless errores.empty?\n      errores.each { |e| warn "[DEBIAN-FECHA-D329] ❌ #{e}" }\n      exit 1\n    end\n    aplicados.grep(/\\Aargus_debian_snapshot=/).each { |a| warn "[DEBIAN-FECHA-D329] aplicado #{a}" }\n    puts fecha\n  else\n    aplicados.grep(/\\Aargus_lab_llamada_vm_limite_s=/).each { |a| warn "[DEBIAN-FECHA-D329] aplicado #{a}" }\n    puts limite\n  end\nend\n', 420), 'scripts/emecas/test_lab_comun.rb': ('# frozen_string_literal: true\n# [DEBIAN-FECHA-D329] tests de lab_comun.rb (anfitrión; sin gemas: biblioteca estándar y un directorio temporal).\n# Cada caso comprueba el valor Y que el error o el aviso salen, para que un validador que lo aceptara todo falle aquí.\nrequire "tmpdir"\nrequire_relative "lab_comun"\n\nAHORA = Time.utc(2026, 11, 17, 6, 0, 0)\n$fallos = 0\n$casos = 0\n\ndef caso(nombre, contenido)\n  Dir.mktmpdir do |d|\n    ruta = File.join(d, "all.yml")\n    File.write(ruta, contenido)\n    r = ArgusLabComun.cargar(ruta, AHORA)\n    ok = yield(*r)\n    $casos += 1\n    $fallos += 1 unless ok\n    puts "#{ok ? \'✅\' : \'❌\'} #{nombre}"\n  end\nend\n\ncaso("fecha y límite válidos", "argus_debian_snapshot: \\"20261115T000000Z\\"\\nargus_lab_llamada_vm_limite_s: 30\\n") do |f, l, e, a, ap|\n  f == "20261115T000000Z" && l == 30 && e.empty? && a.empty? && ap.size == 2\nend\ncaso("fecha ausente -> error de fabricante", "argus_lab_llamada_vm_limite_s: 30\\n") do |f, _l, e, _a, _ap|\n  f.nil? && e.size == 1 && e[0].include?("falta") && e[0].include?("ERROR DE FABRICANTE")\nend\ncaso("fecha mal formada", "argus_debian_snapshot: \\"2026-11-15\\"\\n") do |f, _l, e, _a, _ap|\n  f.nil? && e.size == 1 && e[0].include?("mal formado")\nend\ncaso("fecha sin comillas (YAML la lee como número o texto) se trata igual",\n     "argus_debian_snapshot: 20261115\\n") do |f, _l, e, _a, _ap|\n  f.nil? && e.size == 1 && e[0].include?("mal formado")\nend\ncaso("fecha imposible (30 de febrero)", "argus_debian_snapshot: \\"20260230T000000Z\\"\\n") do |f, _l, e, _a, _ap|\n  f.nil? && e.size == 1 && e[0].include?("no es una fecha real")\nend\ncaso("fecha anterior a la caja", "argus_debian_snapshot: \\"20240101T000000Z\\"\\n") do |f, _l, e, _a, _ap|\n  f.nil? && e.size == 1 && e[0].include?("fuera de límites")\nend\ncaso("fecha futura", "argus_debian_snapshot: \\"20261118T000000Z\\"\\n") do |f, _l, e, _a, _ap|\n  f.nil? && e.size == 1 && e[0].include?("fuera de límites")\nend\ncaso("límite ausente -> 60 con aviso", "argus_debian_snapshot: \\"20261115T000000Z\\"\\n") do |f, l, e, a, ap|\n  f && l == 60 && e.empty? && a.size == 1 && a[0].include?("falta") && ap.any? { |x| x.include?("defecto del código") }\nend\ncaso("límite fuera de rango -> 60 con aviso", "argus_debian_snapshot: \\"20261115T000000Z\\"\\nargus_lab_llamada_vm_limite_s: 5\\n") do |_f, l, e, a, _ap|\n  l == 60 && e.empty? && a.size == 1 && a[0].include?("mal")\nend\ncaso("límite de tipo erróneo -> 60 con aviso", "argus_debian_snapshot: \\"20261115T000000Z\\"\\nargus_lab_llamada_vm_limite_s: \\"30\\"\\n") do |_f, l, _e, a, _ap|\n  l == 60 && a.size == 1\nend\ncaso("fichero que no es un mapa", "- uno\\n- dos\\n") do |f, _l, e, _a, _ap|\n  f.nil? && e.size == 1 && e[0].include?("falta")\nend\n\nputs "#{$casos - $fallos}/#{$casos} casos"\nexit($fallos.zero? ? 0 : 1)\n', 420)}

MODIFICA = {'Vagrantfile': ('887911f7c8a550c170fe15bd0dfc935f28cc044ce75c71866eca80509656fb42', [('        "(formato: [a-z0-9-], de 1 a 64 caracteres; p. ej. hospital-lab)"\nend\n', '        "(formato: [a-z0-9-], de 1 a 64 caracteres; p. ej. hospital-lab)"\nend\n\n# [DEBIAN-FECHA-D329] lo común a todas las lentes (todas las VMs), de ansible/inventory/group_vars/all.yml, con la\n# validación de scripts/emecas/lab_comun.rb (formato y límites en su cabecera; la misma que usa make kernel-homogeneo).\n# Sin fecha de Debian válida Vagrant para aquí: es un error de fabricante (de aRGus), no del despliegue.\nrequire File.join(__dir__, "scripts", "emecas", "lab_comun")\nARGUS_GROUP_VARS_TODOS = File.expand_path(File.join("ansible", "inventory", "group_vars", "all.yml"), __dir__)\nARGUS_DEBIAN_SNAPSHOT, _limite_vm, errores_comun, avisos_comun, _aplicados_comun = ArgusLabComun.cargar(ARGUS_GROUP_VARS_TODOS)\navisos_comun.each { |a| warn "[DEBIAN-FECHA-D329] AVISO #{a}" }\nunless errores_comun.empty?\n  abort "[DEBIAN-FECHA-D329] #{ARGUS_GROUP_VARS_TODOS}:\\n  " + errores_comun.join("\\n  ")\nend\n', 1), ('  APT_ESPERA\n\n', '  APT_ESPERA\n\n  # [DEBIAN-FECHA-D329] DEBT-LAB-KERNEL-HOMOGENEO-001 (decisión de Alonso DAY328-329): todas las VMs con el mismo Debian.\n  # Va a nivel de config, justo después de apt-espera y en cada up: apunta las fuentes de Debian a snapshot.debian.org en\n  # argus_debian_snapshot (all.yml), para si queda alguna otra fuente de Debian sin fijar, deja la VM en el estado de esa\n  # fecha (full-upgrade) y comprueba que el kernel de la fecha queda instalado. Arrancarlo exige reiniciar: en EMECAS,\n  # vagrant up --provision-with apt-espera,debian-fecha; vagrant reload --no-provision; vagrant provision; y make\n  # kernel-homogeneo lo comprueba con uname -r. Medido DAY328: sin esto, unattended-upgrades (y en defender el apt-get de\n  # linux-headers-amd64) instalaba el último kernel de bookworm-security en plena corrida, más ~120 paquetes.\n  config.vm.provision "shell", name: "debian-fecha", run: "always", args: [ARGUS_DEBIAN_SNAPSHOT], inline: <<-\'DEBIAN_FECHA\'\n    set -eu\n    TS="$1"\n    case "$TS" in\n      [0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]T[0-9][0-9][0-9][0-9][0-9][0-9]Z) ;;\n      *) echo "❌ debian-fecha: marca \'$TS\' mal formada (AAAAMMDDTHHMMSSZ)"; exit 1 ;;\n    esac\n    B=https://snapshot.debian.org/archive\n    L=/etc/apt/sources.list\n    printf \'%s\\n\' \\\n      "# [DEBIAN-FECHA-D329] generado por el Vagrantfile desde ansible/inventory/group_vars/all.yml (argus_debian_snapshot); no editar a mano" \\\n      "deb [check-valid-until=no] $B/debian/$TS/ bookworm main" \\\n      "deb [check-valid-until=no] $B/debian/$TS/ bookworm-updates main" \\\n      "deb [check-valid-until=no] $B/debian-security/$TS/ bookworm-security main" > "$L.argus-nuevo"\n    mv "$L.argus-nuevo" "$L"\n    DEBIAN_RE=\'(deb|security|ftp[a-z0-9.]*)\\.debian\\.org\'\n    OTRAS=$(grep -lE "^[[:space:]]*(deb|URIs:).*$DEBIAN_RE" /etc/apt/sources.list.d/*.list /etc/apt/sources.list.d/*.sources 2>/dev/null || true)\n    if [ -n "$OTRAS" ]; then\n      echo "❌ debian-fecha: fuentes de Debian sin fijar a $TS: $OTRAS"; exit 1\n    fi\n    apt-get update -o Acquire::Retries=3\n    DEBIAN_FRONTEND=noninteractive apt-get -y -o Acquire::Retries=3 \\\n      -o Dpkg::Options::=--force-confdef -o Dpkg::Options::=--force-confold full-upgrade\n    if apt-cache policy | grep -E "$DEBIAN_RE"; then\n      echo "❌ debian-fecha: apt sigue viendo Debian fuera de $TS (líneas de arriba)"; exit 1\n    fi\n    K=$(dpkg-query -W -f=\'${Depends}\' linux-image-amd64 | sed -n \'s/.*linux-image-\\([0-9][^ ,]*\\).*/\\1/p\' | head -n 1)\n    if [ -z "$K" ] || ! dpkg-query -W -f=\'${Status}\' "linux-image-$K" 2>/dev/null | grep -q \'install ok installed\'; then\n      echo "❌ debian-fecha: el kernel de la fecha no quedó instalado (linux-image-amd64 -> ${K:-?})"; exit 1\n    fi\n    echo "✅ debian-fecha: Debian en $TS; kernel de la fecha $K (en marcha: $(uname -r); arranca tras reiniciar)"\n  DEBIAN_FECHA\n\n', 1), ('      # bookworm-backports para libhtp2 >= 0.5.50 (Suricata 7.x)\n      echo "deb http://deb.debian.org/debian bookworm-backports main" \\\n', '      # bookworm-backports para libhtp2 >= 0.5.50 (Suricata 7.x), en la fecha de Debian del lab [DEBIAN-FECHA-D329]\n      echo "deb [check-valid-until=no] https://snapshot.debian.org/archive/debian/#{ARGUS_DEBIAN_SNAPSHOT}/ bookworm-backports main" \\\n', 1)])}

def main():
    aplicar = "--apply" in sys.argv[1:]
    if not os.path.isfile("Vagrantfile") or not os.path.isfile("Makefile"):
        sys.exit("❌ ejecutar desde la raíz del repo")
    errores, resultado = [], {}
    for ruta in NUEVOS:
        if os.path.exists(ruta):
            errores.append("ya existe " + ruta)
    for ruta, (sha_partida, cambios) in MODIFICA.items():
        datos = open(ruta, "rb").read()
        h = hashlib.sha256(datos).hexdigest()
        if h != sha_partida:
            errores.append("%s: sha256 de partida %s, esperado %s" % (ruta, h, sha_partida))
            continue
        texto = datos.decode("utf-8")
        for viejo, nuevo, veces in cambios:
            n = texto.count(viejo)
            if n != veces:
                errores.append("%s: ancla %d veces, esperadas %d: %r" % (ruta, n, veces, viejo[:90]))
            else:
                texto = texto.replace(viejo, nuevo)
        resultado[ruta] = texto
    if errores:
        print("❌ no se escribe nada:")
        for e in errores:
            print("   - " + e)
        sys.exit(1)
    if not aplicar:
        print("✅ todo cuadra (sin --apply no se escribe nada): %d nuevos, %d modificados" % (len(NUEVOS), len(resultado)))
        return
    for ruta, (contenido, modo) in NUEVOS.items():
        os.makedirs(os.path.dirname(ruta) or ".", exist_ok=True)
        with open(ruta, "w", encoding="utf-8", newline="") as f:
            f.write(contenido)
        os.chmod(ruta, modo)
        print("  + %s  sha256=%s" % (ruta, hashlib.sha256(contenido.encode()).hexdigest()))
    for ruta, texto in resultado.items():
        with open(ruta, "w", encoding="utf-8", newline="") as f:
            f.write(texto)
        print("  ~ %s  sha256=%s" % (ruta, hashlib.sha256(texto.encode()).hexdigest()))
    print("✅ aplicado")

if __name__ == "__main__":
    main()
